export interface MoodleUserAttemptsResponse {
  attempts: MoodleQuizAttempt[];
  /** list of warnings */
  warnings: MoodleWarning[];
}

/** Decodes a {@link MoodleUserAttemptsResponse}; `undefined` when `json` isn't an object. */
export function decodeMoodleUserAttemptsResponse(json: unknown): MoodleUserAttemptsResponse | undefined {
  const object = asJsonObject(json);
  if (object === undefined) return undefined;
  return {
    attempts: decodeList(object["attempts"], decodeMoodleQuizAttempt) ?? [],
    warnings: decodeList(object["warnings"], decodeMoodleWarning) ?? [],
  };
}

export function encodeMoodleUserAttemptsResponse(value: MoodleUserAttemptsResponse): JsonObject {
  return {
    "attempts": value.attempts.map((item) => encodeMoodleQuizAttempt(item)),
    "warnings": value.warnings.map((item) => encodeMoodleWarning(item)),
  };
}

export interface MoodleUserBestGradeResponse {
  /** Whether the user has a grade on the given quiz. */
  hasGrade: boolean;
  /** The grade (only if the user has a grade). */
  grade: number | null;
  /** The grade to pass the quiz (only if set). */
  gradeToPass: number | null;
  /** list of warnings */
  warnings: MoodleWarning[];
}

/** Decodes a {@link MoodleUserBestGradeResponse}; `undefined` when `json` isn't an object. */
export function decodeMoodleUserBestGradeResponse(json: unknown): MoodleUserBestGradeResponse | undefined {
  const object = asJsonObject(json);
  if (object === undefined) return undefined;
  return {
    hasGrade: decodeBoolean(object["hasgrade"]) ?? false,
    grade: decodeNumber(object["grade"]) ?? null,
    gradeToPass: decodeNumber(object["gradetopass"]) ?? null,
    warnings: decodeList(object["warnings"], decodeMoodleWarning) ?? [],
  };
}

export function encodeMoodleUserBestGradeResponse(value: MoodleUserBestGradeResponse): JsonObject {
  return {
    "hasgrade": value.hasGrade,
    "grade": value.grade,
    "gradetopass": value.gradeToPass,
    "warnings": value.warnings.map((item) => encodeMoodleWarning(item)),
  };
}

